#!/usr/bin/env bash
# ==============================================================================
# OmniFood POS — Remote OTA Release Publisher
# ==============================================================================
# Reads the release manifest generated by build_pos_apk.sh, validates artifact
# presence and digests, uploads APKs to Cloudflare R2 (nhilos-pos bucket), and
# registers the releases in the PostgreSQL app_releases catalog.
#
# Usage:
#   scripts/publish_pos_release.sh [OPTIONS]
#
# Options:
#   --dist-dir DIR          Directory containing built APKs and release_manifest.json.
#                           Default: <repo>/dist/release_candidate
#   --channel CHANNEL       Target distribution channel: pilot or production.
#                           Default: pilot
#   --min-from CODE         Minimum installed versionCode that may upgrade to this
#                           release (Rule R3). Default: 1
#   --notes "TEXT"          Optional changelog/release notes shown on the terminal.
#   --mandatory             Mark the release as mandatory (forces update).
#   -h, --help              Show this help message.
# ==============================================================================

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"
BACKEND_DIR="${ROOT_DIR}/apps/admin_backend"

DIST_DIR="${ROOT_DIR}/dist/release_candidate"
CHANNEL="pilot"
MIN_FROM=1
NOTES=""
MANDATORY=false

while [[ $# -gt 0 ]]; do
    case "$1" in
        --dist-dir)
            DIST_DIR="$(cd "${ROOT_DIR}" && realpath -m -- "$2")"
            shift 2
            ;;
        --channel)
            CHANNEL="$2"
            shift 2
            ;;
        --min-from)
            MIN_FROM="$2"
            shift 2
            ;;
        --notes)
            NOTES="$2"
            shift 2
            ;;
        --mandatory)
            MANDATORY=true
            shift
            ;;
        -h|--help)
            sed -n '2,20p' "$0" | sed 's/^# \?//'
            exit 0
            ;;
        *)
            echo "Unknown option: $1" >&2
            exit 1
            ;;
    esac
done

MANIFEST_FILE="${DIST_DIR}/release_manifest.json"

if [ ! -f "${MANIFEST_FILE}" ]; then
    echo "ERROR: release_manifest.json not found in ${DIST_DIR}." >&2
    echo "Run scripts/build_pos_apk.sh first to build and sign the release artifacts." >&2
    exit 1
fi

if [ ! -f "${BACKEND_DIR}/.env" ]; then
    echo "ERROR: .env file missing in ${BACKEND_DIR} (required for R2 credentials)." >&2
    exit 1
fi

NODE_ARGS=(
    "--manifest" "${MANIFEST_FILE}"
    "--channel" "${CHANNEL}"
    "--min-from" "${MIN_FROM}"
)

if [ -n "${NOTES}" ]; then
    NODE_ARGS+=("--notes" "${NOTES}")
fi

if [ "${MANDATORY}" = true ]; then
    NODE_ARGS+=("--mandatory")
fi

echo "🚀 Invoking release publication runner..."
cd "${BACKEND_DIR}"
npx ts-node -r tsconfig-paths/register src/scripts/publish-release.ts "${NODE_ARGS[@]}"
